const $=id=>document.getElementById(id), clone=o=>structuredClone(o), KEY='uri-classroom-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const names=['김민준','이서연','박도윤','최하윤','정시우','강지우','조예준','윤서아','장주원','임지안','한이준','오하린','서도현','신수아','권지호','황예린','안준우','송다은','류건우','홍채원','전현우','고유나','문우진','양서윤'];
function initial(demo=true){const students=demo?names.map((name,i)=>({id:uid(),no:i+1,name,gender:i%2?'F':'M',photo:'',front:false,avoid:''})):[];return {version:1,className:'3학년 2반',groups:6,seats:4,columns:3,students,layout:Array.from({length:24},(_,i)=>students[i]?.id||null),locks:[],date:today(),history:[],draft:null,view:'teacher',photos:true,colors:true,motion:false};}
let firstVisit=false;try{firstVisit=!localStorage.getItem(KEY);}catch{}
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=initial();}catch{state=initial();}let selected=null,undos=[],redos=[];let navStack=['board'],currentPage='board';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='● 이 기기에 자동 저장';}catch{$('saved').textContent='저장 공간 부족 · 백업해 주세요';toast('저장하지 못했습니다. 사진 크기를 줄이거나 백업해 주세요.');}}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
function tab(id,remember=true){if(remember&&id!==currentPage){navStack.push(id);if(navStack.length>20)navStack.shift();}currentPage=id;document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==id);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===id));if(id==='students')renderStudents();if(id==='history')renderHistory();updateEditControls();}
function snapshot(){return {layout:clone(state.layout),locks:clone(state.locks),date:state.date,groups:state.groups,seats:state.seats,columns:state.columns,students:clone(state.students),className:state.className,spatial:clone(state.spatial)};}
function beginEdit(){recordAction();if(!state.draft)state.draft={base:snapshot(),rotation:false};}
function student(id){return state.students.find(s=>s.id===id);}
function pos(i){return `모둠 위치 ${Math.floor(i/state.seats)+1} · 자리 ${i%state.seats+1}`;}
function violations(layout=state.layout){ensureSpatial();const issues=[];const seen=new Set();layout.forEach((id,i)=>{if(!id)return;if(!activeSlot(i))issues.push('책상이 없는 위치에 배정된 학생이 있습니다.');if(seen.has(id))issues.push('중복 배정된 학생이 있습니다.');seen.add(id);const s=student(id);if(!s){issues.push('명단에 없는 학생이 있습니다.');return;}if(s.front&&!state.spatial.groups[Math.floor(i/state.seats)].front)issues.push(`${s.name}: 앞자리 조건을 확인하세요.`);if(s.avoid){const j=layout.indexOf(s.avoid);if(j>=0&&Math.floor(i/state.seats)===Math.floor(j/state.seats))issues.push(`${s.name}: 떨어뜨리기 대상과 같은 모둠입니다.`);}});if(seen.size<state.students.length)issues.push(`미배치 학생 ${state.students.length-seen.size}명`);return [...new Set(issues)];}
function render(){const focusSeat=document.activeElement?.dataset?.seat;const oldSeats=captureSeatPositions();ensureSpatial();save();$('autoWeekly').checked=state.autoWeekly!==false;renderAutoStatus();$('className').value=state.className;$('count').textContent=state.students.length;$('effectiveDate').value=state.date;$('groupCount').value=state.groups;$('seatCount').innerHTML=Array.from({length:16},(_,i)=>`<option>${i+1}</option>`).join('');$('seatCount').value=state.seats;$('columns').value=state.columns;$('photos').checked=state.photos;$('colors').checked=state.colors;$('motion').checked=state.motion;document.body.classList.toggle('student-mode',state.view==='student');document.body.classList.toggle('no-motion',state.motion);$('teacher').classList.toggle('selected',state.view==='teacher');$('student').classList.toggle('selected',state.view==='student');$('viewHint').textContent=state.view==='teacher'?'교탁에서 학생들을 바라보는 방향':'교실 뒤에서 칠판을 바라보는 방향';$('groups').style.setProperty('--cols',state.columns);$('status').textContent=state.draft?(state.draft.rotation?'다음 주 배치 · 미확정':'수정 중 · 미확정'):'현재 배치';$('dateLabel').textContent=`${state.className} · ${state.date}`;$('cancel').hidden=!state.draft;$('cycle').textContent=Array.from({length:state.groups},(_,i)=>i+1).join(' → ')+' ↺';$('example').textContent=new Set(state.spatial.groups.map(g=>g.cells.length)).size===1?`위치 1 · 자리 1 → 위치 2 · 자리 2 / 마지막 자리 ${state.spatial.groups[0].cells.length} → 자리 1`:'모둠별 자리 수가 다릅니다. 같은 수로 맞춘 뒤 주간 순환을 사용할 수 있어요.';
$('groups').innerHTML=Array.from({length:state.groups},(_,g)=>`<div class="group" style="${groupStyle(g)}"><div class="group-title"><span class="group-drag" aria-hidden="true">⠿</span><span class="group-number">${String(g+1).padStart(2,'0')}</span> 모둠</div><div class="seats" style="grid-template-columns:repeat(${geometry(state.spatial.groups[g]).width},minmax(0,1fr));grid-template-rows:repeat(${geometry(state.spatial.groups[g]).height},minmax(0,1fr))">${Array.from({length:state.seats},(_,k)=>k).filter(k=>state.spatial.groups[g].cells[k]).map(k=>{const i=g*state.seats+k,s=student(state.layout[i]);return `<button data-student="${esc(s?.id||'')}" class="seat ${s?'':'empty'} ${selected===i?'selected':''} ${state.locks.includes(i)?'locked':''}" style="${deskStyle(g,k)}" data-seat="${i}" title="${esc(pos(i)+' · '+(s?.name||'빈자리'))}" aria-label="${esc(pos(i)+' '+(s?.name||'빈자리'))}"><span class="num">${k+1}</span>${state.locks.includes(i)?'<span class="lock-icon" aria-label="고정됨"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3"></path></svg></span>':''}${s?`${state.photos?(s.photo?`<img src="${esc(s.photo)}" alt="${esc(s.name)}">`:`<span class="avatar">${esc(s.name.slice(0,1))}</span>`):''}<strong class="${state.colors?(s.gender==='M'?'male':s.gender==='F'?'female':'neutral'):'neutral'}">${esc(s.name)}</strong>`:'빈자리'}</button>`;}).join('')}</div></div>`).join('');
$('selection').textContent=selected===null?'좌석을 선택해 주세요':`${pos(selected)} · ${student(state.layout[selected])?.name||'빈자리'}`;const issues=violations();$('issues').innerHTML=issues.map(s=>`<div class="issue">${esc(s)}</div>`).join('');$('confirm').disabled=issues.length>0;renderSpatial();renderPolishedUI();updateEditControls();renderBackupInfo();renderGroupStats();animateSeatChanges(oldSeats);if(focusSeat!==undefined)document.querySelector?.(`[data-seat="${focusSeat}"]`)?.focus?.({preventScroll:true});}
$('groups').addEventListener('click',e=>{const b=e.target.closest('[data-seat]');if(!b||document.body.classList.contains('presentation'))return;const i=+b.dataset.seat;if(selected===null){selected=i;render();return;}if(selected===i){selected=null;render();return;}if(state.locks.includes(i)||state.locks.includes(selected)){toast('고정된 자리입니다. 고정을 해제한 뒤 이동하세요.');return;}beginEdit();[state.layout[i],state.layout[selected]]=[state.layout[selected],state.layout[i]];selected=null;render();});
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('className').onchange=e=>{beginEdit();state.className=e.target.value.trim()||'우리 반';render();};
$('teacher').onclick=()=>{state.view='teacher';render();};$('student').onclick=()=>{state.view='student';render();};$('photos').onchange=e=>{state.photos=e.target.checked;render();};$('colors').onchange=e=>{state.colors=e.target.checked;render();};$('motion').onchange=e=>{state.motion=e.target.checked;render();};
