$('openPaste').onclick=()=>{$('pasteReview').innerHTML='';$('pasteDialog').showModal();};$('pasteCommit').onclick=()=>{const rows=$('pasteText').value.trim().split(/\r?\n/).filter(Boolean);const list=rows.map((line,i)=>{const parts=line.trim().split(/[\t, ]+/);let no=i+1;if(/^\d+$/.test(parts[0]))no=+parts.shift();const name=parts.shift()||'';const sex=parts.shift()||'';return {id:uid(),no,name,gender:/^(남|남학생|남자|M)$/i.test(sex)?'M':/^(여|여학생|여자|F)$/i.test(sex)?'F':'',photo:'',front:false,avoid:''};});if(!list.length||list.some(s=>!s.name))return toast('이름을 확인해 주세요.');if(new Set(list.map(s=>s.no)).size!==list.length)return toast('중복된 번호가 있습니다.');$('pasteReview').innerHTML=`<div class="note">${list.map(s=>`${esc(s.no)} ${esc(s.name)} (${s.gender==='M'?'남':s.gender==='F'?'여':'미설정'})`).join('<br>')}</div><button class="primary" id="pasteFinal">${list.length}명 등록</button>`;$('pasteFinal').onclick=()=>{if(replaceStudents(list))$('pasteDialog').close();};};
