function drawGrid(){if(!roster)return;const c=$('rosterCanvas');c.width=sourceCanvas.width;c.height=sourceCanvas.height;const x=c.getContext('2d');x.drawImage(sourceCanvas,0,0);const g=grid(),w=c.width,h=c.height;x.strokeStyle='#328d62';x.lineWidth=Math.max(2,w/600);for(let r=0;r<g.rows;r++)for(let k=0;k<g.cols;k++){const bx=w*g.side+k*w*(1-2*g.side)/g.cols,by=h*g.top+r*h*(1-g.top-g.bottom)/g.rows,bw=w*(1-2*g.side)/g.cols,bh=h*(1-g.top-g.bottom)/g.rows;x.strokeRect(bx,by,bw,bh);x.setLineDash([5,5]);x.beginPath();x.moveTo(bx,by+bh*g.ratio);x.lineTo(bx+bw,by+bh*g.ratio);x.stroke();x.setLineDash([]);}}
