$('rosterFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('importStatus').textContent='명부를 읽고 있습니다…';$('importControls').hidden=true;$('importReview').innerHTML='';$('importCommit').hidden=true;pdfTexts=[];roster=null;try{if(f.type==='application/pdf'||/\.pdf$/i.test(f.name)){const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise;if(pdf.numPages!==1)throw Error('한 페이지 PDF를 올려 주세요.');const page=await pdf.getPage(1);pdfViewport=page.getViewport({scale:Math.min(2,1800/page.getViewport({scale:1}).width)});sourceCanvas.width=pdfViewport.width;sourceCanvas.height=pdfViewport.height;await page.render({canvasContext:sourceCanvas.getContext('2d'),viewport:pdfViewport}).promise;pdfTexts=(await page.getTextContent()).items.map(t=>({text:t.str,x:pdfViewport.convertToViewportPoint(t.transform[4],t.transform[5])[0],y:pdfViewport.convertToViewportPoint(t.transform[4],t.transform[5])[1]}));}else{const im=await imageFile(f),k=Math.min(1,1800/im.width);sourceCanvas.width=im.width*k;sourceCanvas.height=im.height*k;sourceCanvas.getContext('2d').drawImage(im,0,0,sourceCanvas.width,sourceCanvas.height);}roster=true;$('importControls').hidden=false;drawGrid();$('importStatus').textContent='초록색 칸을 학생 한 명의 사진과 이름에 맞춰 주세요. 점선 아래에서 이름을 읽습니다.';}catch(err){$('importStatus').textContent=`읽기 실패: ${err.message||'네트워크 연결과 파일 형식을 확인해 주세요.'}`;}};
function crop(sx,sy,sw,sh,outputW=160){const c=document.createElement('canvas');c.width=outputW;c.height=Math.round(outputW*sh/sw);c.getContext('2d').drawImage(sourceCanvas,sx,sy,sw,sh,0,0,c.width,c.height);return c;}
$('extract').onclick=async()=>{if(!roster)return;const g=grid();if(g.cols<1||g.rows<1||g.cols>12||g.rows>12||g.top+g.bottom>=.95||g.side>=.45||g.ratio<=0||g.ratio>=1)return toast('칸 수와 여백을 확인해 주세요.');$('extract').disabled=true;let worker;try{const w=sourceCanvas.width,h=sourceCanvas.height,bw=w*(1-2*g.side)/g.cols,bh=h*(1-g.top-g.bottom)/g.rows;let texts=pdfTexts;if(texts.filter(t=>/[가-힣]/.test(t.text)).length<2){$('importStatus').textContent='한글 인식 모듈을 준비하고 있습니다. 처음에는 시간이 걸릴 수 있어요.';if(!window.Tesseract)await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js');worker=await window.Tesseract.createWorker('kor+eng');const {data}=await worker.recognize(sourceCanvas);texts=(data.words||[]).map(t=>({text:t.text,x:t.bbox.x0,y:(t.bbox.y0+t.bbox.y1)/2}));}imported=[];for(let r=0;r<g.rows;r++)for(let k=0;k<g.cols;k++){const sx=w*g.side+k*bw,sy=h*g.top+r*bh;const raw=texts.filter(t=>t.x>=sx&&t.x<sx+bw&&t.y>=sy+bh*g.ratio&&t.y<sy+bh).sort((a,b)=>a.y-b.y||a.x-b.x).map(t=>t.text).join(' ').trim();const match=raw.match(/[가-힣]{2,5}/);imported.push({id:uid(),no:imported.length+1,name:match?.[0]||'',gender:'',photo:crop(sx+bw*.06,sy+bh*.03,bw*.88,bh*(g.ratio-.06)).toDataURL('image/jpeg',.8),front:false,avoid:''});}renderImport();$('importStatus').textContent='각 사진과 이름을 확인해 주세요. 이름은 직접 수정할 수 있고 빈 칸은 체크를 해제하세요.';$('importCommit').hidden=false;}catch(err){$('importStatus').textContent='이름 자동 인식에 실패했습니다. 사진만 추출하여 이름을 직접 입력할 수 있습니다.';const w=sourceCanvas.width,h=sourceCanvas.height,bw=w*(1-2*g.side)/g.cols,bh=h*(1-g.top-g.bottom)/g.rows;imported=Array.from({length:g.cols*g.rows},(_,i)=>({id:uid(),no:i+1,name:'',gender:'',photo:crop(w*g.side+i%g.cols*bw,h*g.top+Math.floor(i/g.cols)*bh,bw,bh*g.ratio).toDataURL('image/jpeg',.8),front:false,avoid:''}));renderImport();$('importCommit').hidden=false;}finally{if(worker)await worker.terminate();$('extract').disabled=false;}};
function renderImport(){$('importReview').innerHTML=imported.map((s,i)=>`<div class="review-card" data-review="${i}"><label><input class="include" type="checkbox" checked> ${i+1}번 등록</label><img src="${s.photo}" alt="추출한 사진 ${i+1}"><input class="review-name" value="${esc(s.name)}" placeholder="이름 확인·입력" aria-label="이름"><select class="review-gender" aria-label="성별"><option value="">성별 미설정</option><option value="M">남학생</option><option value="F">여학생</option></select><button class="recrop">사진 영역 다시 자르기</button></div>`).join('');}
$('importReview').onclick=e=>{if(!e.target.classList.contains('recrop'))return;const idx=+e.target.closest('[data-review]').dataset.review;const d=document.createElement('dialog');d.innerHTML='<form method="dialog"><button class="close">×</button></form><h3>사진 영역 다시 자르기</h3><p>사진의 왼쪽 위와 오른쪽 아래를 차례로 눌러 주세요.</p><canvas style="width:100%;touch-action:none"></canvas>';document.body.append(d);const c=d.querySelector('canvas');c.width=sourceCanvas.width;c.height=sourceCanvas.height;c.getContext('2d').drawImage(sourceCanvas,0,0);let start=null;c.onclick=ev=>{const b=c.getBoundingClientRect(),p={x:(ev.clientX-b.left)*c.width/b.width,y:(ev.clientY-b.top)*c.height/b.height};if(!start){start=p;const ctx=c.getContext('2d');ctx.fillStyle='#328d62';ctx.fillRect(p.x-5,p.y-5,10,10);return;}const x=Math.min(start.x,p.x),y=Math.min(start.y,p.y),w=Math.abs(start.x-p.x),h=Math.abs(start.y-p.y);if(w<10||h<10){start=null;return;}imported[idx].photo=crop(x,y,w,h).toDataURL('image/jpeg',.82);e.target.closest('[data-review]').querySelector('img').src=imported[idx].photo;d.close();};d.onclose=()=>d.remove();d.showModal();};
$('importCommit').onclick=()=>{const result=[];document.querySelectorAll('[data-review]').forEach(row=>{if(!row.querySelector('.include').checked)return;const s=clone(imported[+row.dataset.review]);s.name=row.querySelector('.review-name').value.trim();s.gender=row.querySelector('.review-gender').value;s.no=result.length+1;result.push(s);});if(!result.length||result.some(s=>!s.name))return toast('등록할 학생의 이름을 모두 입력해 주세요.');if(replaceStudents(result)){$('importDialog').close();toast(`${result.length}명의 사진 명부를 등록했습니다.`);}};
