function defaultSpace(){const shape=Math.min(6,Math.ceil(Math.sqrt(state.seats))),w=shape*2,h=Math.ceil(state.seats/shape)*2;let cols=Math.min(state.columns,state.groups,Math.floor(24/w));cols=Math.max(cols,Math.ceil(state.groups/Math.floor(24/h)));let gap=(cols*(w+1)<=24&&Math.ceil(state.groups/cols)*(h+1)<=24)?1:0;return {width:Math.max(8,cols*w+(cols-1)*gap),height:Math.max(8,Math.ceil(state.groups/cols)*h+(Math.ceil(state.groups/cols)-1)*gap),groups:Array.from({length:state.groups},(_,g)=>({x:g%cols*(w+gap),y:Math.floor(g/cols)*(h+gap),cols:shape,front:g<cols}))};}
