function upgradeCells(p){if(!p?.groups)return;for(const g of p.groups){if(!Array.isArray(g.cells))g.cells=rectCells(state.seats,g.cols||2);if(!Number.isInteger(g.rotation))g.rotation=0;}}
function geometry(g){let cells=(g.cells||rectCells(state.seats,g.cols||2)).map(c=>({...c}));for(let r=0;r<(g.rotation||0)%4;r++){const height=Math.max(...cells.map(c=>c.y))+1;cells=cells.map(c=>({x:height-1-c.y,y:c.x}));}return {cells,width:Math.max(...cells.map(c=>c.x))+1,height:Math.max(...cells.map(c=>c.y))+1};}
function cellsValid(g){return Array.isArray(g.cells)&&g.cells.length>0&&g.cells.length<=state.seats&&g.cells.every(c=>Number.isInteger(c.x)&&Number.isInteger(c.y)&&c.x>=0&&c.y>=0&&c.x<6&&c.y<6)&&new Set(g.cells.map(c=>c.x+','+c.y)).size===g.cells.length&&Number.isInteger(g.rotation)&&g.rotation>=0&&g.rotation<4;}
function spaceValid(p){if(!p||!Number.isInteger(p.width)||p.width<8||p.width>24||!Number.isInteger(p.height)||p.height<8||p.height>24||!Array.isArray(p.groups)||p.groups.length!==state.groups)return false;upgradeCells(p);return p.groups.every((g,i)=>Number.isInteger(g.x)&&Number.isInteger(g.y)&&cellsValid(g)&&canPlace(p,i,g));}
