function activeSlot(i){return !!state.spatial.groups[Math.floor(i/state.seats)]?.cells[i%state.seats];}

function renderSpatial(){upgradeCells(state.spatial);const p=state.spatial;$('room').style.setProperty('--map-width',p.width);$('room').style.setProperty('--map-height',p.height);$('groups').style.setProperty('--space-w',p.width);$('groups').style.setProperty('--space-h',p.height);$('spaceWidth').value=p.width;$('spaceHeight').value=p.height;editingGroup=Math.min(editingGroup,state.groups-1);$('editGroup').innerHTML=p.groups.map((g,i)=>`<option value="${i}" ${i===editingGroup?'selected':''}>모둠 위치 ${i+1}</option>`).join('');$('shapeCols').innerHTML=Array.from({length:state.seats},(_,i)=>i+1).filter(n=>state.seats%n===0).map(n=>`<option value="${n}" ${n===p.groups[editingGroup].cols?'selected':''}>${n}열 × ${state.seats/n}행</option>`).join('');$('frontGroup').checked=!!p.groups[editingGroup].front;const ed=$('spaceEditor');ed.style.setProperty('--space-w',p.width);ed.style.setProperty('--space-h',p.height);ed.innerHTML=Array.from({length:p.width*p.height},(_,i)=>`<button class="grid-cell" data-cell="${i}" aria-label="가로 ${i%p.width+1}, 세로 ${Math.floor(i/p.width)+1}"></button>`).join('')+p.groups.map((g,i)=>`<button class="edit-group ${i===editingGroup?'chosen':''}" data-group="${i}" style="${groupStyle(i)}" aria-label="모둠 ${i+1} 이동"><strong>${i+1}모둠 ${g.front?'· 앞자리':''}</strong><span>${g.cells.length}자리 · ${geometry(g).width}×${geometry(g).height}</span></button>`).join('');$('editorStatus').textContent=`${editingGroup+1}모둠 선택됨 · 빈 칸을 누르거나 모둠을 드래그하세요. 겹치는 위치에는 놓을 수 없습니다.`;}
