let drag=null,suppressClick=false;
$('spaceEditor').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-group]');if(!b)return;e.preventDefault();const p=state.spatial,rect=$('spaceEditor').getBoundingClientRect();editingGroup=+b.dataset.group;drag={id:e.pointerId,b,index:editingGroup,startX:e.clientX,startY:e.clientY,x:p.groups[editingGroup].x,y:p.groups[editingGroup].y,cw:rect.width/p.width,ch:rect.height/p.height};b.setPointerCapture(e.pointerId);b.classList.add('dragging');});
