function packGroups(p,gap=1){let x=0,y=0,rowH=0;for(const g of p.groups){const q=geometry(g),w=q.width*2,h=q.height*2;if(x+w>24){x=0;y+=rowH+gap;rowH=0;}if(y+h>24)return gap===1?packGroups(p,0):false;g.x=x;g.y=y;x+=w+gap;rowH=Math.max(rowH,h);}p.width=24;p.height=Math.max(8,y+rowH);return true;}
function applyDeskShape(all=false){if(!draftCells.length)return toast('책상을 한 개 이상 배치하세요.');if(reorderMode)return toast('순서 지정을 마치거나 취소한 뒤 적용하세요.');const minX=Math.min(...draftCells.map(c=>c.x)),minY=Math.min(...draftCells.map(c=>c.y)),cells=draftCells.map(c=>({x:c.x-minX,y:c.y-minY}));if(state.locks.some(i=>(all||Math.floor(i/state.seats)===editingGroup)&&i%state.seats>=cells.length))return toast('삭제할 책상에 고정 설정이 있습니다. 고정을 먼저 해제해 주세요.');const oldSeats=state.seats,n=Math.max(oldSeats,cells.length),p=clone(state.spatial),layout=Array(state.groups*n).fill(null),locks=[];state.layout.forEach((id,i)=>layout[Math.floor(i/oldSeats)*n+i%oldSeats]=id);state.locks.forEach(i=>locks.push(Math.floor(i/oldSeats)*n+i%oldSeats));p.groups.forEach((g,i)=>{if(all||i===editingGroup){g.cells=clone(cells);g.rotation=0;g.cols=Math.max(...cells.map(c=>c.x))+1;}});const displaced=[];layout.forEach((id,i)=>{if(id&&!p.groups[Math.floor(i/n)].cells[i%n]){displaced.push(id);layout[i]=null;}});const open=layout.map((id,i)=>!id&&p.groups[Math.floor(i/n)].cells[i%n]?i:-1).filter(i=>i>=0);if(displaced.length>open.length)return toast('학생을 옮길 빈자리가 부족합니다. 책상 수를 늘리거나 명단을 조정해 주세요.');displaced.forEach((id,i)=>layout[open[i]]=id);const old=state.seats;state.seats=n;let packed=false;if(!spaceValid(p)){packed=true;if(!packGroups(p)||!spaceValid(p)){state.seats=old;return toast('교실 격자에 모두 들어가지 않습니다. 모둠 크기를 줄여 주세요.');}}state.seats=old;if((packed||displaced.length)&&!confirm(`${packed?'모양이 커져 교실의 모둠 위치를 자동 정렬합니다. ':''}${displaced.length?displaced.length+'명은 다른 빈자리로 이동합니다. ':''}적용할까요?`))return;beginEdit();state.seats=n;state.spatial=p;state.layout=layout;state.locks=locks.filter(i=>p.groups[Math.floor(i/n)].cells[i%n]);selected=null;render();$('shapeDialog').close();toast(all?'모든 모둠에 모양과 순환 순서를 복제했습니다.':'모둠 안 책상 모양과 순환 순서를 저장했습니다.');}
