function dayIndex(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return NaN;const t=Date.parse(date+'T00:00:00Z');return Number.isFinite(t)&&new Date(t).toISOString().slice(0,10)===date?t/86400000:NaN;}
