function prettyDate(date){const t=dayIndex(date);if(!Number.isFinite(t))return '날짜 확인';const d=new Date(t*86400000);return `${String(d.getUTCMonth()+1).padStart(2,'0')}.${String(d.getUTCDate()).padStart(2,'0')} (${['일','월','화','수','목','금','토'][d.getUTCDay()]})`;}
