async function saveBackupFile(){const timestamp=new Date().toISOString(),safeName=String(state.className||'우리반').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,40),fileName=`우리반자리_${safeName}_${today()}.json`;const payload={...clone(state),lastBackupAt:timestamp,lastBackupVerified:false};let verified=false;try{if(typeof window.showSaveFilePicker==='function'){try{const handle=await window.showSaveFilePicker({suggestedName:fileName,types:[{description:'우리 반 자리 백업',accept:{'application/json':['.json']}}]});const writer=await handle.createWritable();payload.lastBackupVerified=true;await writer.write(JSON.stringify(payload));await writer.close();verified=true;}catch(err){if(err.name==='AbortError')return toast('백업 저장을 취소했습니다.');if(!['SecurityError','NotAllowedError','TypeError'].includes(err.name))throw err;download(JSON.stringify(payload),fileName);}}else download(JSON.stringify(payload),fileName);state.lastBackupAt=timestamp;state.lastBackupVerified=verified;save();renderBackupInfo();toast(verified?'백업 파일을 저장했습니다.':'백업 다운로드를 요청했습니다. 다운로드 폴더를 확인해 주세요.');}catch{toast('백업을 저장하지 못했습니다. 파일 저장 권한과 여유 공간을 확인해 주세요.');}}
