/* GROUP_STATS_MODULE: additive, read-only confirmed-history statistics. */
function computeGroupStats(history,currentStudents){
  const ids=new Set((Array.isArray(currentStudents)?currentStudents:[]).filter(s=>s&&typeof s.id==='string').map(s=>s.id));
  const counts=new Map(),studentRecordCounts=new Map();
  ids.forEach(id=>{counts.set(id,new Map());studentRecordCounts.set(id,0);});
  let recordCount=0;const signatures=new Set();
  for(const h of Array.isArray(history)?history:[]){
    if(!h||typeof h.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Number.isFinite(Date.parse(h.date+'T00:00:00Z'))||new Date(h.date+'T00:00:00Z').toISOString().slice(0,10)!==h.date||!Number.isInteger(h.groups)||h.groups<1||h.groups>128||!Number.isInteger(h.seats)||h.seats<1||h.seats>128||!Array.isArray(h.layout)||h.layout.length!==h.groups*h.seats||h.layout.length>2048)continue;
    if(!h.layout.every(id=>id===null||typeof id==='string'))continue;
    const occupants=h.layout.filter(id=>id!==null);if(new Set(occupants).size!==occupants.length)continue;
    const signature=JSON.stringify([h.date,h.groups,h.seats,h.layout]);if(signatures.has(signature))continue;signatures.add(signature);recordCount++;
    const present=new Set(occupants.filter(id=>ids.has(id)));present.forEach(id=>studentRecordCounts.set(id,studentRecordCounts.get(id)+1));
    for(let g=0;g<h.groups;g++){
      const members=h.layout.slice(g*h.seats,(g+1)*h.seats).filter(id=>ids.has(id));
      for(let a=0;a<members.length;a++)for(let b=a+1;b<members.length;b++){
        const x=members[a],y=members[b];counts.get(x).set(y,(counts.get(x).get(y)||0)+1);counts.get(y).set(x,(counts.get(y).get(x)||0)+1);
      }
    }
  }
  return {recordCount,studentRecordCounts,counts};
}
function groupStatsRows(stats,id){return state.students.filter(s=>s.id!==id).map(s=>({id:s.id,no:s.no,name:s.name,count:stats.counts.get(id)?.get(s.id)||0})).sort((a,b)=>b.count-a.count||((Number(a.no)||0)-(Number(b.no)||0))||String(a.name).localeCompare(String(b.name),'ko'));}
let statsSelectedId='';
function renderGroupStats(){
  const stats=computeGroupStats(state.history,state.students),s=selected===null?null:student(state.layout[selected]);
  $('showGroupStats').disabled=state.students.length<2;
  if(!s){$('groupStatsBasis').textContent=`확정 배치 ${stats.recordCount}회 기준`;$('groupStatsSummary').innerHTML=`<p class="stats-empty">${stats.recordCount?'학생을 선택하면 함께한 친구와 횟수를 보여드려요.':'배치를 확정하면 모둠 기록이 쌓여요.'}</p>`;}
  else{
    const n=stats.studentRecordCounts.get(s.id)||0;$('groupStatsBasis').textContent=`${s.name} · 확정 배치 ${n}회 기준`;
    const top=groupStatsRows(stats,s.id).filter(row=>row.count>0).slice(0,3);
    $('groupStatsSummary').innerHTML=top.length?`<ul class="stats-peer-list">${top.map(row=>`<li><span>${esc(row.name)}</span><strong>${row.count}<small>회</small></strong></li>`).join('')}</ul>`:`<p class="stats-empty">${n?'아직 함께한 친구의 기록이 없어요.':'이 학생이 포함된 확정 기록이 아직 없어요.'}</p>`;
  }
  if($('groupStatsDialog').open)renderGroupStatsDialog(stats);
}
function renderGroupStatsDialog(stats=computeGroupStats(state.history,state.students)){
  const candidates=state.students.slice().sort((a,b)=>(Number(a.no)||0)-(Number(b.no)||0));
  if(!candidates.some(s=>s.id===statsSelectedId))statsSelectedId=candidates[0]?.id||'';
  $('statsStudentSelect').innerHTML=candidates.map(s=>`<option value="${esc(s.id)}" ${s.id===statsSelectedId?'selected':''}>${esc(s.no)}번 · ${esc(s.name)}</option>`).join('');
  const s=student(statsSelectedId),n=stats.studentRecordCounts.get(statsSelectedId)||0;
  $('statsDialogBasis').textContent=s?`${s.name}이(가) 포함된 확정 배치 ${n}회 · 전체 중복 제외 기록 ${stats.recordCount}회`:'명단에 학생을 등록하면 기록을 확인할 수 있어요.';
  const rows=s?groupStatsRows(stats,s.id):[];
  $('statsTableBody').innerHTML=rows.length?rows.map(row=>`<tr><td>${esc(row.no)}</td><th scope="row">${esc(row.name)}</th><td><span class="stats-count ${row.count?'has-count':''}">${row.count}<small>회</small></span></td></tr>`).join(''):'<tr><td colspan="3" class="stats-table-empty">비교할 다른 학생이 없습니다.</td></tr>';
}
$('showGroupStats').onclick=()=>{const s=selected===null?null:student(state.layout[selected]);statsSelectedId=s?.id||state.students[0]?.id||'';renderGroupStatsDialog();$('groupStatsDialog').showModal();};
$('statsStudentSelect').onchange=e=>{statsSelectedId=e.target.value;renderGroupStatsDialog();};
